{
  "rules": [
    {
      "category": "just_cause_eviction",
      "title": "Los Angeles Rent Stabilization Ordinance Just Cause Eviction Protections and Relocation Assistance",
      "requirement": "A landlord may only recover possession of a rental unit for specified at-fault or no-fault grounds, and must provide statutory notice and pay required relocation assistance for qualifying no-fault evictions.",
      "requirement_es": "Un propietario solo puede recuperar la posesión de una unidad de alquiler por causales específicas con culpa o sin culpa, y debe entregar una notificación legal y pagar la asistencia para la reubicación requerida en desalojos sin culpa calificados.",
      "key_value": {
        "label": "Relocation assistance fee range",
        "value": "$7,300 to $18,300 (base amounts adjusted annually)"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Tenant received advance written notice prior to tenancy agreement that subdivision application for condo/co-op was on file or approved and building would be demolished or relocated",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Tenant received advance written notice prior to tenancy agreement that application to convert building to condo/co-op project was on file or approved",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Owner recovers unit for a resident manager replacing an existing resident manager in the same unit",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Government order to vacate building housing rental unit due to hazardous conditions caused by a natural disaster",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "1979-05-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Affirmative defense to unlawful detainer; landlord liability in civil action for unpaid relocation damages plus reasonable attorney fees and costs; willful/knowing false statements in notices or declarations punishable as a misdemeanor with fine up to $1,000 and/or imprisonment up to six months.",
      "source_citation": "L.A. Mun. Code § 151.09",
      "quote": {
        "chunk": "c83",
        "start_words": "A landlord may bring an action",
        "end_words": "one of the following grounds:"
      },
      "confidence": 0.95
    }
  ]
}
